self.KB_CONTENT["card:728068"]={"id":"card:728068","ty":"card","sourceId":"728068","title":"建立訂單時，出現“此訂單有未確認之報價變更單!”，要怎麼處理？","ver":"GP4X","topic":"變更單","keywords":["變更單","報價單","客戶","訂單"],"y":"error","answer":"因訂單有未確認的報價單存在。解決方法：先到『報價變更單建立作業』，將報價變更單確認後，在到『客戶訂單建立作業』，建立此報價單的訂單資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
