self.KB_CONTENT["card:791994"]={"id":"card:791994","ty":"card","sourceId":"791994","title":"『製令成本分析表』中的『選擇性質 (MOC.TA030)』為何？","ver":"GP4以上","topic":"分析表","keywords":["分析表","製令","單頭"],"y":"other","answer":"* 其性質依製令單頭檔之性質碼做判斷。* 區分為1.廠內製令、2.託外製令及3.全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
