self.KB_CONTENT["field:781995"]={"id":"field:781995","ty":"field","sourceId":"781995","title":"抵押借款科目","ver":"GP4以上","topic":"","keywords":[],"job":"票據科目設定作業","code":"MD011","answer":"* 可點選(icon)或按[F2]查詢會計科目資料。* 本欄位可空白不輸入，若有輸入必須為獨立科目或明細科目。","file":"fields.jsonl"};
